package com.bank.band;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class SalaryBandDemo {
    private static final Logger log = Logger.getLogger("SalaryBand");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", 95000.0),
            new Employee(2L, "Priya", 250000.0),
            new Employee(3L, "Amit", 120000.0),
            new Employee(4L, "Sneha", 180000.0)
        );
        SalaryBandService service = new SalaryBandService();
        SalaryRange range = service.salaryRange(staff);
        log.info(() -> "Lowest paid : " + range.getMinName() + " (" + range.getMin() + ")");
        log.info(() -> "Highest paid: " + range.getMaxName() + " (" + range.getMax() + ")");
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final double salary;
    Employee(Long id, String name, double salary) { this.id = id; this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in model/SalaryRange.java ───
class SalaryRange {
    private final String minName; private final double min;
    private final String maxName; private final double max;
    SalaryRange(String minName, double min, String maxName, double max) {
        this.minName = minName; this.min = min; this.maxName = maxName; this.max = max;
    }
    String getMinName() { return minName; } double getMin() { return min; }
    String getMaxName() { return maxName; } double getMax() { return max; }
}

// ─── Would be in service/SalaryBandService.java ───
class SalaryBandService {
    // teeing: feed every employee to minBy AND maxBy, then merge into a SalaryRange — one pass.
    SalaryRange salaryRange(List<Employee> employees) {
        return employees.stream().collect(teeing(
            minBy(Comparator.comparingDouble(Employee::getSalary)),
            maxBy(Comparator.comparingDouble(Employee::getSalary)),
            (lo, hi) -> {
                Employee min = lo.orElseThrow(() -> new IllegalStateException("no employees"));
                Employee max = hi.orElseThrow(() -> new IllegalStateException("no employees"));
                return new SalaryRange(min.getName(), min.getSalary(), max.getName(), max.getSalary());
            }));
    }
}
